-- Stark English catalog v1, sourced from Notion Tasks; all teaching episodes are DRAFT.
-- Separate browseable catalog metadata from unpublished student lesson bodies.
create table if not exists public.stark_catalog_collections(
 id uuid primary key default gen_random_uuid(),
 course_id uuid not null references public.courses(id),
 slug text not null,
 title text not null,
 kind text not null check(kind in ('series','movie','short','interview')),
 cefr text not null,
 description text not null default '',
 expected_lessons integer,
 expected_reviews integer not null default 0,
 source_record_count integer not null default 0,
 status text not null check(status in ('concept','source_records','approved','published')),
 sort_order integer not null default 0,
 series_id uuid references public.series(id),
 updated_at timestamptz not null default now(),
 unique(course_id,slug)
);
create table if not exists public.stark_catalog_units(
 id uuid primary key default gen_random_uuid(),
 collection_id uuid not null references public.stark_catalog_collections(id) on delete cascade,
 code text not null unique,
 sequence_no integer not null check(sequence_no>0),
 block_number integer,
 kind text not null check(kind in ('lesson','review')),
 cefr text not null,
 stage text not null,
 working_title text not null,
 title_verified boolean not null default false,
 proposed_outcome text not null default '',
 source_url text,
 source_instructions text,
 source_deliverable text,
 source_completion text,
 episode_id uuid references public.episodes(id),
 status text not null default 'draft' check(status in ('draft','approved','published')),
 updated_at timestamptz not null default now(),
 unique(collection_id,sequence_no)
);
create index if not exists stark_catalog_collection_kind on public.stark_catalog_collections(course_id,kind,sort_order);
create index if not exists stark_catalog_unit_collection on public.stark_catalog_units(collection_id,sequence_no);
alter table public.stark_catalog_collections enable row level security;
alter table public.stark_catalog_units enable row level security;
revoke all on public.stark_catalog_collections,public.stark_catalog_units from anon,authenticated;

insert into public.series(course_id,slug,name)
select c.id,x.slug,x.title from public.courses c,
 (values ('svo','The SVO Protocol'),('dvc','The English Way — DVC')) x(slug,title)
where c.slug='stark-english'
on conflict(course_id,slug) do nothing;

