insert into public.stark_catalog_collections(course_id,slug,title,kind,cefr,description,
 expected_lessons,expected_reviews,source_record_count,status,sort_order,series_id)
select c.id,x.slug,x.title,x.kind,x.cefr,x.description,
 x.expected_lessons,x.expected_reviews,x.source_record_count,x.status,x.sort_order,s.id
from supplied x cross join public.courses c
left join public.series s on s.course_id=c.id and s.slug=x.slug
where c.slug='stark-english'
on conflict(course_id,slug) do nothing;

