  stage text,title text,verified boolean,outcome text,source_url text,instructions text,deliverable text,completion text)
)
insert into public.episodes(series_id,code,title,description,lesson_body,level,minutes,status)
select s.id,x.code,
 case when x.unit_type='review' then x.title else x.code||' · '||x.title end,
 'Curriculum draft imported from Stark Notion Tasks. Source material and assessment must be verified before publication.',
 '',
 case when x.cefr='A1' then 'A1' when x.cefr='B1' then 'B1' else 'A2' end,
 case when x.unit_type='review' then 30 else 60 end,
 'draft'
from supplied x join public.courses c on c.slug='stark-english'
 join public.series s on s.course_id=c.id and s.slug=x.collection
on conflict(code) do nothing;

