select col.id,x.code,x.position,x.block,x.unit_type,x.cefr,x.stage,x.title,x.verified,x.outcome,
 x.source_url,x.instructions,x.deliverable,x.completion,e.id
from supplied x join public.courses c on c.slug='stark-english'
join public.stark_catalog_collections col on col.course_id=c.id and col.slug=x.collection
join public.episodes e on e.code=x.code
on conflict(code) do nothing;

-- Public: approved-for-display catalog descriptions only. No private Notion source URLs or exercise texts.
create or replace function public.stark_english_catalog()
returns jsonb language sql stable security definer set search_path='' as $$
select coalesce(jsonb_agg(jsonb_build_object(
 'slug',t.slug,'title',t.title,'kind',t.kind,'cefr',t.cefr,
 'description',t.description,'expectedLessons',t.expected_lessons,
 'expectedReviews',t.expected_reviews,'sourceRecords',t.source_record_count,
 'status',t.status,'seriesId',t.series_id
) order by t.kind,t.sort_order),'[]'::jsonb)
from public.stark_catalog_collections t
join public.courses c on c.id=t.course_id where c.slug='stark-english';
$$;
create or replace function public.stark_english_collection(p_slug text)
returns jsonb language sql stable security definer set search_path='' as $$
select coalesce((
 select jsonb_build_object(
 'slug',t.slug,'title',t.title,'kind',t.kind,'cefr',t.cefr,
 'description',t.description,'expectedLessons',t.expected_lessons,
 'expectedReviews',t.expected_reviews,'sourceRecords',t.source_record_count,
 'status',t.status,
 'units',coalesce((
 select jsonb_agg(jsonb_build_object('code',u.code,'order',u.sequence_no,'block',u.block_number,
  'kind',u.kind,'cefr',u.cefr,'stage',u.stage,'workingTitle',u.working_title,
  'titleVerified',u.title_verified,'outcome',u.proposed_outcome,'status',u.status)
 order by u.sequence_no)
 from public.stark_catalog_units u where u.collection_id=t.id
 ),'[]'::jsonb)
 ) from public.stark_catalog_collections t
 join public.courses c on c.id=t.course_id where c.slug='stark-english' and t.slug=p_slug
),'null'::jsonb);
$$;
-- Staff-only source information for curriculum approval.
create or replace function public.stark_english_collection_sources(p_slug text)
returns table(code text,source_url text,source_instructions text,source_deliverable text,source_completion text)
language plpgsql stable security definer set search_path='' as $$
begin
 if auth.uid() is null or app_private.staff_rank(app_private.staff_level())<3
 then raise exception 'Teacher permission required';end if;
 return query
 select u.code,u.source_url,u.source_instructions,u.source_deliverable,u.source_completion
 from public.stark_catalog_units u join public.stark_catalog_collections t on t.id=u.collection_id
 join public.courses c on c.id=t.course_id
 where c.slug='stark-english' and t.slug=p_slug order by u.sequence_no;
end $$;
revoke all on function public.stark_english_catalog(),public.stark_english_collection(text) from public,anon,authenticated;
grant execute on function public.stark_english_catalog(),public.stark_english_collection(text) to anon,authenticated;
revoke all on function public.stark_english_collection_sources(text) from public,anon,authenticated;
grant execute on function public.stark_english_collection_sources(text) to authenticated;